insert into public.sources(id,org,title,url,use_ar,use_en,reviewed) values
(30,'NIH Office of Dietary Supplements','Vitamin A and Carotenoids: Fact Sheet for Health Professionals','https://ods.od.nih.gov/factsheets/VitaminA-HealthProfessional/','الاحتياج والحد الأعلى والتداخلات وتحذير الحمل','Needs, upper limit, interactions, pregnancy warning',false),
(31,'NIH Office of Dietary Supplements','Vitamin E: Fact Sheet for Health Professionals','https://ods.od.nih.gov/factsheets/VitaminE-HealthProfessional/','الاحتياج والحد الأعلى والتداخلات','Needs, upper limit, interactions',false),
(32,'NIH Office of Dietary Supplements','Vitamin K: Fact Sheet for Health Professionals','https://ods.od.nih.gov/factsheets/VitaminK-HealthProfessional/','الاحتياج الكافي والتداخل مع الوارفارين','Adequate intake, warfarin interaction',false),
(33,'NIH Office of Dietary Supplements','Vitamin B6: Fact Sheet for Health Professionals','https://ods.od.nih.gov/factsheets/VitaminB6-HealthProfessional/','الاحتياج والحد الأعلى والاعتلال العصبي والتداخلات','Needs, upper limit, neuropathy, interactions',false),
(34,'NIH Office of Dietary Supplements','Thiamin: Fact Sheet for Health Professionals','https://ods.od.nih.gov/factsheets/Thiamin-HealthProfessional/','الاحتياج والتداخلات','Needs, interactions',false),
(35,'NIH Office of Dietary Supplements','Niacin: Fact Sheet for Health Professionals','https://ods.od.nih.gov/factsheets/Niacin-HealthProfessional/','الاحتياج والحد الأعلى والآثار الجانبية والتداخلات','Needs, upper limit, side effects, interactions',false),
(36,'NIH Office of Dietary Supplements','Biotin: Fact Sheet for Health Professionals','https://ods.od.nih.gov/factsheets/Biotin-HealthProfessional/','الاحتياج الكافي وتأثيره على التحاليل','Adequate intake, lab-test interference',false),
(37,'NIH Office of Dietary Supplements','Iodine: Fact Sheet for Health Professionals','https://ods.od.nih.gov/factsheets/Iodine-HealthProfessional/','الاحتياج والحد الأعلى والتداخلات','Needs, upper limit, interactions',false),
(38,'U.S. Food and Drug Administration','Biotin Interference with Troponin Lab Tests: Assays Subject to Biotin Interference','https://www.fda.gov/medical-devices/in-vitro-diagnostics/biotin-interference-troponin-lab-tests-assays-subject-biotin-interference','تحذير FDA من تأثير البيوتين على التحاليل','FDA warning on biotin and lab tests',false);
insert into public.nutrients(id,builtin,sort,name_ar,name_en,hint_ar,hint_en,unit,dose_rows,note_ar,note_en,source_ids,reviewed) values
('vita',false,90,'فيتامين A','Vitamin A','الرؤية والمناعة','Vision and immunity','mcg','[{"a0": 0, "a1": 0, "sx": "all", "rda": "400–500", "ul": "600"}, {"a0": 1, "a1": 3, "sx": "all", "rda": "300", "ul": "600"}, {"a0": 4, "a1": 8, "sx": "all", "rda": "400", "ul": "900"}, {"a0": 9, "a1": 13, "sx": "all", "rda": "600", "ul": "1,700"}, {"a0": 14, "a1": 18, "sx": "m", "rda": "900", "ul": "2,800"}, {"a0": 14, "a1": 18, "sx": "f", "rda": "700", "ul": "2,800"}, {"a0": 14, "a1": 18, "sx": "p", "rda": "750", "ul": "2,800"}, {"a0": 14, "a1": 18, "sx": "l", "rda": "1,200", "ul": "2,800"}, {"a0": 19, "a1": 50, "sx": "m", "rda": "900", "ul": "3,000"}, {"a0": 19, "a1": 50, "sx": "f", "rda": "700", "ul": "3,000"}, {"a0": 19, "a1": 50, "sx": "p", "rda": "770", "ul": "3,000"}, {"a0": 19, "a1": 50, "sx": "l", "rda": "1,300", "ul": "3,000"}, {"a0": 51, "a1": 110, "sx": "m", "rda": "900", "ul": "3,000"}, {"a0": 51, "a1": 110, "sx": "f", "rda": "700", "ul": "3,000"}]'::jsonb,'القيم بالميكروغرام من مكافئ نشاط الريتينول (RAE). للرضّع: 400 لأول 6 أشهر و500 من 7 إلى 12 شهراً (احتياج كافٍ). الحد الأعلى يخص فيتامين A الجاهز (Retinol وإستراته) من المصادر الحيوانية والمكملات فقط، ولا يشمل بيتا كاروتين. تجاوز الحد الأعلى من فيتامين A الجاهز وبعض أدوية الريتينويد قد يسبب تشوهات خلقية، لذلك يُنصح الحوامل ومن قد يحملن والمرضعات بعدم أخذ جرعات عالية.','Values are mcg retinol activity equivalents (RAE). Infants: 400 for 0–6 months and 500 for 7–12 months (adequate intake). The upper limit applies only to preformed vitamin A (retinol and its esters) from animal foods and supplements, not to beta-carotene. Preformed vitamin A above the upper limit and some retinoid drugs can cause birth defects, so women who are or might be pregnant, and those breastfeeding, should not take high doses.','{30}',false),
('vite',false,100,'فيتامين E','Vitamin E','مضاد للأكسدة','Antioxidant','mg','[{"a0": 0, "a1": 0, "sx": "all", "rda": "4–5", "ul": ""}, {"a0": 1, "a1": 3, "sx": "all", "rda": "6", "ul": "200"}, {"a0": 4, "a1": 8, "sx": "all", "rda": "7", "ul": "300"}, {"a0": 9, "a1": 13, "sx": "all", "rda": "11", "ul": "600"}, {"a0": 14, "a1": 18, "sx": "all", "rda": "15", "ul": "800"}, {"a0": 14, "a1": 18, "sx": "l", "rda": "19", "ul": "800"}, {"a0": 19, "a1": 110, "sx": "all", "rda": "15", "ul": "1,000"}, {"a0": 19, "a1": 50, "sx": "l", "rda": "19", "ul": "1,000"}]'::jsonb,'بالملغ من ألفا توكوفيرول. للرضّع: 4 ملغ لأول 6 أشهر و5 من 7 إلى 12 شهراً (احتياج كافٍ)، ولا يُحدد لهم حد أعلى، ومصدرهم حليب الأم أو الحليب الصناعي والغذاء فقط. الحد الأعلى يشمل كل أشكال ألفا توكوفيرول في المكملات.','mg of alpha-tocopherol. Infants: 4 mg for 0–6 months and 5 mg for 7–12 months (adequate intake); no upper limit is set for infants and breast milk, formula and food should be their only sources. The upper limit covers all forms of supplemental alpha-tocopherol.','{31}',false),
('vitk',false,110,'فيتامين K','Vitamin K','تخثر الدم','Blood clotting','mcg','[{"a0": 0, "a1": 0, "sx": "all", "rda": "2–2.5", "ul": ""}, {"a0": 1, "a1": 3, "sx": "all", "rda": "30", "ul": ""}, {"a0": 4, "a1": 8, "sx": "all", "rda": "55", "ul": ""}, {"a0": 9, "a1": 13, "sx": "all", "rda": "60", "ul": ""}, {"a0": 14, "a1": 18, "sx": "all", "rda": "75", "ul": ""}, {"a0": 19, "a1": 110, "sx": "m", "rda": "120", "ul": ""}, {"a0": 19, "a1": 110, "sx": "f", "rda": "90", "ul": ""}]'::jsonb,'هذه قيم احتياج كافٍ (AI) وليست RDA. لا يوجد حد أعلى لأن سمّيته منخفضة. من يتناول الوارفارين يحافظ على كمية ثابتة من فيتامين K يومياً، لأن التغيّر المفاجئ يغيّر تأثير الدواء.','These are adequate intakes (AI), not RDAs. There is no upper limit because toxicity is low. People on warfarin should keep their vitamin K intake consistent, because sudden changes alter the drug''s effect.','{32}',false),
('b6',false,120,'فيتامين B6','Vitamin B6','البيريدوكسين','Pyridoxine','mg','[{"a0": 0, "a1": 0, "sx": "all", "rda": "0.1–0.3", "ul": ""}, {"a0": 1, "a1": 3, "sx": "all", "rda": "0.5", "ul": "30"}, {"a0": 4, "a1": 8, "sx": "all", "rda": "0.6", "ul": "40"}, {"a0": 9, "a1": 13, "sx": "all", "rda": "1.0", "ul": "60"}, {"a0": 14, "a1": 18, "sx": "m", "rda": "1.3", "ul": "80"}, {"a0": 14, "a1": 18, "sx": "f", "rda": "1.2", "ul": "80"}, {"a0": 14, "a1": 18, "sx": "p", "rda": "1.9", "ul": "80"}, {"a0": 14, "a1": 18, "sx": "l", "rda": "2.0", "ul": "80"}, {"a0": 19, "a1": 50, "sx": "all", "rda": "1.3", "ul": "100"}, {"a0": 19, "a1": 50, "sx": "p", "rda": "1.9", "ul": "100"}, {"a0": 19, "a1": 50, "sx": "l", "rda": "2.0", "ul": "100"}, {"a0": 51, "a1": 110, "sx": "m", "rda": "1.7", "ul": "100"}, {"a0": 51, "a1": 110, "sx": "f", "rda": "1.5", "ul": "100"}]'::jsonb,'الاستعمال الطويل لجرعات عالية من البيريدوكسين قد يسبب اعتلالاً عصبياً حسياً شديداً ومتفاقماً، وسُجّلت حالات بجرعات أقل من 500 ملغ يومياً. الحد الأعلى الأمريكي للبالغين 100 ملغ يومياً، بينما حددت الهيئة الأوروبية EFSA عام 2023 حداً أعلى 12 ملغ يومياً. للرضّع: 0.1 ملغ لأول 6 أشهر و0.3 من 7 إلى 12 شهراً.','Long-term high-dose pyridoxine can cause severe, progressive sensory neuropathy, with reports at doses below 500 mg/day. The US adult upper limit is 100 mg/day, while EFSA (2023) set 12 mg/day. Infants: 0.1 mg for 0–6 months and 0.3 mg for 7–12 months.','{33}',false),
('b1',false,130,'فيتامين B1','Vitamin B1','الثيامين','Thiamin','mg','[{"a0": 0, "a1": 0, "sx": "all", "rda": "0.2–0.3", "ul": ""}, {"a0": 1, "a1": 3, "sx": "all", "rda": "0.5", "ul": ""}, {"a0": 4, "a1": 8, "sx": "all", "rda": "0.6", "ul": ""}, {"a0": 9, "a1": 13, "sx": "all", "rda": "0.9", "ul": ""}, {"a0": 14, "a1": 18, "sx": "m", "rda": "1.2", "ul": ""}, {"a0": 14, "a1": 18, "sx": "f", "rda": "1.0", "ul": ""}, {"a0": 14, "a1": 18, "sx": "p", "rda": "1.4", "ul": ""}, {"a0": 14, "a1": 18, "sx": "l", "rda": "1.4", "ul": ""}, {"a0": 19, "a1": 110, "sx": "m", "rda": "1.2", "ul": ""}, {"a0": 19, "a1": 110, "sx": "f", "rda": "1.1", "ul": ""}, {"a0": 19, "a1": 50, "sx": "p", "rda": "1.4", "ul": ""}, {"a0": 19, "a1": 50, "sx": "l", "rda": "1.4", "ul": ""}]'::jsonb,'لا يوجد حد أعلى معتمد لعدم تسجيل آثار ضارة من الكميات العالية. للرضّع: 0.2 ملغ لأول 6 أشهر و0.3 من 7 إلى 12 شهراً.','No upper limit is set because no adverse effects from high intakes have been reported. Infants: 0.2 mg for 0–6 months and 0.3 mg for 7–12 months.','{34}',false),
('b3',false,140,'فيتامين B3','Vitamin B3','النياسين','Niacin','mg','[{"a0": 0, "a1": 0, "sx": "all", "rda": "2–4", "ul": ""}, {"a0": 1, "a1": 3, "sx": "all", "rda": "6", "ul": "10"}, {"a0": 4, "a1": 8, "sx": "all", "rda": "8", "ul": "15"}, {"a0": 9, "a1": 13, "sx": "all", "rda": "12", "ul": "20"}, {"a0": 14, "a1": 18, "sx": "m", "rda": "16", "ul": "30"}, {"a0": 14, "a1": 18, "sx": "f", "rda": "14", "ul": "30"}, {"a0": 14, "a1": 18, "sx": "p", "rda": "18", "ul": "30"}, {"a0": 14, "a1": 18, "sx": "l", "rda": "17", "ul": "30"}, {"a0": 19, "a1": 110, "sx": "m", "rda": "16", "ul": "35"}, {"a0": 19, "a1": 110, "sx": "f", "rda": "14", "ul": "35"}, {"a0": 19, "a1": 50, "sx": "p", "rda": "18", "ul": "35"}, {"a0": 19, "a1": 50, "sx": "l", "rda": "17", "ul": "35"}]'::jsonb,'القيم بالملغ من مكافئ النياسين (NE)، عدا قيمة الرضّع لأول 6 أشهر فهي من النياسين الجاهز. الحد الأعلى يخص النياسين المكمّل فقط (حمض النيكوتينيك والنيكوتيناميد) وليس الغذاء، ولا ينطبق على العلاج تحت إشراف طبي. 30 إلى 50 ملغ فأكثر من حمض النيكوتينيك تسبب عادة احمرار الوجه، وجرعات 1,000 إلى 3,000 ملغ يومياً قد تسبب آثاراً أخطر، والاستعمال الطويل بجرعات عالية قد يضر الكبد.','Values are mg niacin equivalents (NE), except the 0–6 month value, which is preformed niacin. The upper limit applies only to supplemental niacin (nicotinic acid and nicotinamide), not food, and not to treatment under medical supervision. 30–50 mg or more of nicotinic acid usually causes flushing; 1,000–3,000 mg/day can cause more serious effects, and high doses over months or years can harm the liver.','{35}',false),
('biotin',false,150,'البيوتين','Biotin','فيتامين B7','Vitamin B7','mcg','[{"a0": 0, "a1": 0, "sx": "all", "rda": "5–6", "ul": ""}, {"a0": 1, "a1": 3, "sx": "all", "rda": "8", "ul": ""}, {"a0": 4, "a1": 8, "sx": "all", "rda": "12", "ul": ""}, {"a0": 9, "a1": 13, "sx": "all", "rda": "20", "ul": ""}, {"a0": 14, "a1": 18, "sx": "all", "rda": "25", "ul": ""}, {"a0": 14, "a1": 18, "sx": "p", "rda": "30", "ul": ""}, {"a0": 14, "a1": 18, "sx": "l", "rda": "35", "ul": ""}, {"a0": 19, "a1": 110, "sx": "all", "rda": "30", "ul": ""}, {"a0": 19, "a1": 50, "sx": "l", "rda": "35", "ul": ""}]'::jsonb,'قيم احتياج كافٍ (AI)، ولا يوجد حد أعلى. الجرعات العالية من البيوتين قد تُفسد نتائج تحاليل تعتمد على تقنية biotin-streptavidin، مثل هرمونات الغدة الدرقية والتروبونين، فتعطي نتائج خاطئة، لذلك يُنصح مقدمو الرعاية بسؤال المرضى عن تناول مكملات البيوتين.','Adequate intakes (AI); no upper limit. High-dose biotin can distort results of biotin-streptavidin lab tests such as thyroid hormones and troponin. Health care providers should ask patients about biotin supplements.','{36,38}',false),
('iodine',false,160,'اليود','Iodine','هرمونات الغدة الدرقية','Thyroid hormones','mcg','[{"a0": 0, "a1": 0, "sx": "all", "rda": "110–130", "ul": ""}, {"a0": 1, "a1": 3, "sx": "all", "rda": "90", "ul": "200"}, {"a0": 4, "a1": 8, "sx": "all", "rda": "90", "ul": "300"}, {"a0": 9, "a1": 13, "sx": "all", "rda": "120", "ul": "600"}, {"a0": 14, "a1": 18, "sx": "all", "rda": "150", "ul": "900"}, {"a0": 14, "a1": 18, "sx": "p", "rda": "220", "ul": "900"}, {"a0": 14, "a1": 18, "sx": "l", "rda": "290", "ul": "900"}, {"a0": 19, "a1": 110, "sx": "all", "rda": "150", "ul": "1,100"}, {"a0": 19, "a1": 50, "sx": "p", "rda": "220", "ul": "1,100"}, {"a0": 19, "a1": 50, "sx": "l", "rda": "290", "ul": "1,100"}]'::jsonb,'الكميات العالية من اليود قد تسبب أعراضاً تشبه نقصه مثل تضخم الغدة وقصورها، وقد تسبب فرط نشاطها والتهابها. مرضى أمراض الغدة المناعية قد يتأثرون بكميات تُعد آمنة لغيرهم. للرضّع: 110 لأول 6 أشهر و130 من 7 إلى 12 شهراً، ومصدرهم الحليب الصناعي والغذاء فقط.','High iodine intake can cause symptoms similar to deficiency, such as goiter and hypothyroidism, and can also cause hyperthyroidism and thyroiditis. People with autoimmune thyroid disease may react to amounts that are safe for others. Infants: 110 for 0–6 months and 130 for 7–12 months; formula and food should be their only sources.','{37}',false);
insert into public.interactions(nutrient_id,supp_ar,supp_en,with_ar,with_en,desc_ar,desc_en,severity,source_ids,sort,reviewed) values
('vita','فيتامين A','Vitamin A','Orlistat','Orlistat','يقلل امتصاص فيتامين A وباقي الفيتامينات الذائبة في الدهون وبيتا كاروتين، وتوصي الشركات المصنعة بفيتامينات متعددة تحتويها','Reduces absorption of vitamin A, other fat-soluble vitamins and beta-carotene; manufacturers recommend a multivitamin containing them','moderate','{30}',1000,false),
('vita','فيتامين A','Vitamin A','الريتينويدات (Acitretin وBexarotene)','Retinoids (acitretin, bexarotene)','أخذها مع مكملات فيتامين A يرفع خطر فرط فيتامين A','Taking them with vitamin A supplements raises the risk of hypervitaminosis A','major','{30}',1010,false),
('vitk','فيتامين K','Vitamin K','Warfarin ومضادات التخثر الكومارينية','Warfarin and other coumarin anticoagulants','التغيّر المفاجئ في كمية فيتامين K يغيّر تأثير الدواء؛ حافظ على كمية ثابتة يومياً','Sudden changes in vitamin K intake alter the drug effect; keep intake consistent','major','{32}',1020,false),
('vitk','فيتامين K','Vitamin K','Orlistat','Orlistat','يقلل امتصاص فيتامين K، ومع الوارفارين قد يزيد زمن البروثرومبين بشكل ملحوظ','Reduces vitamin K absorption; with warfarin it may markedly increase prothrombin time','major','{32}',1030,false),
('vitk','فيتامين K','Vitamin K','المضادات الحيوية (خاصة السيفالوسبورينات مثل Cefoperazone)','Antibiotics (especially cephalosporins such as cefoperazone)','قد تخفض فيتامين K بقتل بكتيريا الأمعاء المنتجة له؛ المكمل غير ضروري عادة إلا مع استعمال يتجاوز عدة أسابيع وغذاء فقير بفيتامين K','May lower vitamin K by killing gut bacteria that make it; supplements are usually unnecessary unless use lasts several weeks and intake is poor','minor','{32}',1040,false),
('vitk','فيتامين K','Vitamin K','Cholestyramine وColestipol','Cholestyramine, colestipol','قد تقلل امتصاص فيتامين K؛ تُراقب حالته مع الاستعمال الطويل','May reduce vitamin K absorption; monitor status with long-term use','minor','{32}',1050,false),
('vite','فيتامين E','Vitamin E','Warfarin ومضادات التخثر والصفائح','Warfarin, anticoagulants and antiplatelets','الجرعات الكبيرة قد تزيد خطر النزف، خاصة مع قلة فيتامين K، والكمية المؤثرة غالباً تتجاوز 400 وحدة دولية يومياً','Large doses may increase bleeding risk, especially with low vitamin K intake; the effective amount probably exceeds 400 IU/day','moderate','{31}',1060,false),
('vite','فيتامين E','Vitamin E','العلاج الكيميائي والإشعاعي','Chemotherapy and radiotherapy','ينصح أطباء الأورام عادة بتجنب مكملات مضادات الأكسدة أثناء العلاج لاحتمال تقليل فعاليته، والأدلة غير حاسمة','Oncologists usually advise against antioxidant supplements during treatment because they might reduce its effectiveness; evidence is inconclusive','moderate','{31}',1070,false),
('vite','فيتامين E','Vitamin E','Simvastatin مع Niacin','Simvastatin with niacin','مزيج مضادات الأكسدة (فيتامين E وC والسيلينيوم وبيتا كاروتين) قلّل ارتفاع الكوليسترول النافع HDL','An antioxidant combination (vitamins E and C, selenium, beta-carotene) blunted the rise in HDL cholesterol','minor','{31}',1080,false),
('b6','فيتامين B6','Vitamin B6','Cycloserine','Cycloserine','يزيد طرح B6 في البول، مما قد يزيد النوبات والسمية العصبية؛ ومكملات B6 قد تمنع ذلك','Increases urinary B6 loss, which may worsen seizures and neurotoxicity; B6 supplements can help prevent this','moderate','{33}',1090,false),
('b6','فيتامين B6','Vitamin B6','مضادات الصرع (Valproate وCarbamazepine وPhenytoin)','Antiepileptics (valproate, carbamazepine, phenytoin)','تزيد تكسير B6، وB6 بجرعة 200 ملغ يومياً قد يخفض مستوى Phenytoin وPhenobarbital في الدم','They increase B6 breakdown; B6 at 200 mg/day may lower blood levels of phenytoin and phenobarbital','moderate','{33}',1100,false),
('b6','فيتامين B6','Vitamin B6','Theophylline','Theophylline','المرضى غالباً لديهم انخفاض في B6 النشط (PLP)، مما قد يسهم في آثار عصبية منها النوبات','Patients often have low active B6 (PLP), which may contribute to neurological side effects including seizures','minor','{33}',1110,false),
('b1','فيتامين B1','Vitamin B1','Furosemide','Furosemide','يرتبط بانخفاض الثيامين، وقد يصل للنقص، بسبب طرحه في البول','Linked to lower thiamin levels, possibly to deficiency, through urinary loss','moderate','{34}',1120,false),
('b1','فيتامين B1','Vitamin B1','5-Fluorouracil','5-Fluorouracil','سُجّلت حالات بري بري واعتلال فيرنيكه، وقد يزيد الدواء استقلاب الثيامين؛ والمكملات قد تعكس بعض التأثير','Cases of beriberi and Wernicke encephalopathy are reported; the drug may increase thiamin metabolism, and supplements might reverse some effects','moderate','{34}',1130,false),
('b3','فيتامين B3','Vitamin B3','Isoniazid وPyrazinamide','Isoniazid, pyrazinamide','تعيق تكوين النياسين وقد تسبب البلاجرا، وزيادة النياسين تمنع ذلك','They interrupt niacin production and can cause pellagra; extra niacin prevents it','moderate','{35}',1140,false),
